package dev.daweapon.type.hub.carnival;

/**
 * Skins for the Carnival NPCs. Their real skins aren't published anywhere this server can read,
 * so these borrow fitting Hub skins until the real ones are found; Doug and the Carnival Cowboy
 * share one skin, as they do on Hypixel.
 */
public enum CarnivalSkin {
    LEADER(
            "",
            ""),
    CHANTELLE(
            "",
            ""),
    DOUG(
            "",
            ""),
    FISHERMAN(
            "",
            ""),
    PIRATEMAN(
            "",
            "");

    private final String texture;
    private final String signature;

    CarnivalSkin(String texture, String signature) {
        this.texture = texture;
        this.signature = signature;
    }

    public String texture() {
        return texture;
    }

    public String signature() {
        return signature;
    }
}
